CREATE TABLE t0(id INTEGER PRIMARY KEY, c0 VARCHAR(10), c1  DEFAULT 'd', c2 REAL NOT NULL DEFAULT 0, c3 NUMERIC COLLATE NOCASE);
CREATE TABLE t1(id INTEGER PRIMARY KEY, c0 TEXT COLLATE NOCASE, c1 INT UNIQUE, c2 REAL, c3 TEXT DEFAULT 'd', ref INTEGER REFERENCES t0(id));
INSERT OR IGNORE INTO t1(c0, c1, c2, c3, ref) VALUES(-224.1, NULL, -154, NULL, 8);
CREATE TABLE t2(id INTEGER PRIMARY KEY, c0 VARCHAR(10) DEFAULT 'd', c1 BLOB, c2 TEXT UNIQUE, ref INTEGER REFERENCES t1(id));
INSERT OR IGNORE INTO t2(c0, c1, c2, ref) VALUES(-513, NULL, -2.007, NULL);
SELECT length('theta'), upper('theta'), lower('theta'), substr('theta', 0, 4), instr('theta', '1e3'), replace('theta', 'a', '_'), trim('theta'), ltrim('theta', 'ab'), hex('theta'), quote('theta'), unicode('theta'), 'theta' LIKE '%', 'theta' GLOB '*[a-m]*', char(82, 719), 'theta' || '1e3', 'theta' < '1e3', 'theta' = '1e3' COLLATE NOCASE;
SELECT length('NULL'), upper('NULL'), lower('NULL'), substr('NULL', 1, 0), instr('NULL', '-7'), replace('NULL', 'é', ''), trim('NULL'), ltrim('NULL', 'ab'), hex('NULL'), quote('NULL'), unicode('NULL'), 'NULL' LIKE '%a_', 'NULL' GLOB '*[a-m]*', char(75, 937), 'NULL' || '-7', 'NULL' < '-7', 'NULL' = '-7' COLLATE NOCASE;
SELECT length('rho'), upper('rho'), lower('rho'), substr('rho', -1, 1), instr('rho', 'delta'), replace('rho', 'é', 'XY'), trim('rho'), ltrim('rho', 'ab'), hex('rho'), quote('rho'), unicode('rho'), 'rho' LIKE '_', 'rho' GLOB 'a*', char(79, 987), 'rho' || 'delta', 'rho' < 'delta', 'rho' = 'delta' COLLATE NOCASE;
SELECT length('pi'), upper('pi'), lower('pi'), substr('pi', 0, 3), instr('pi', 'a%b'), replace('pi', 'e', ''), trim('pi'), ltrim('pi', 'ab'), hex('pi'), quote('pi'), unicode('pi'), 'pi' LIKE '_', 'pi' GLOB '*[a-m]*', char(83, 360), 'pi' || 'a%b', 'pi' < 'a%b', 'pi' = 'a%b' COLLATE NOCASE;
SELECT length('omega'), upper('omega'), lower('omega'), substr('omega', 3, 1), instr('omega', 'xi'), replace('omega', 'e', ''), trim('omega'), ltrim('omega', 'ab'), hex('omega'), quote('omega'), unicode('omega'), 'omega' LIKE 'a%', 'omega' GLOB 'a*', char(85, 890), 'omega' || 'xi', 'omega' < 'xi', 'omega' = 'xi' COLLATE NOCASE;
